-- SQL Server's word sort of nvarchar text as two keys: the text without specials and ignorables, in NFD, then the specials' ranks by position.
CREATE FUNCTION people.legacy_word_text(value text) RETURNS text
  LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
  RETURN rtrim(normalize(regexp_replace(value, '[\u0001\u0002\u0003\u0004\u0005\u0006\u0007\u0008\u000E\u000F\u0010\u0011\u0012\u0013\u0014\u0015\u0016\u0017\u0018\u0019\u001A\u001B\u001C\u001D\u001E\u001F\u007F\u0080\u0081\u0082\u0083\u0084\u0085\u0086\u0087\u0088\u0089\u008A\u008B\u008C\u008D\u008E\u008F\u0090\u0091\u0092\u0093\u0094\u0095\u0096\u0097\u0098\u0099\u009A\u009B\u009C\u009D\u009E\u009F\u0027\uFF07\uFE63\u002D\uFF0D\u208B\u207B\u00AD\u2010\u2011\u2027\u2043\u2012\u2013\uFE58\u2014\u2015\u301C\u3030\uFE31\uFE32\u064B\uFE70\uFE71\u064C\uFE72\u064D\uFE74\u064E\uFE76\uFE77\u064F\uFE78\uFE79\u0650\uFE7A\uFE7B\u0652\uFE7E\uFE7F\u01F6-\u01F9\u0218-\u024F\u02A9-\u02AF\u02DF\u02EA-\u02FF\u0349-\u036F\u0373\u0376-\u0379\u037B-\u037D\u037F-\u0383\u0387\u038B\u038D\u03A2\u03CF\u03D7-\u03D9\u03F3-\u0400\u040D\u0450\u045D\u0487-\u048F\u04CD-\u0530\u0557-\u0558\u0560\u0587-\u0588\u058A-\u0590\u05C4-\u05CF\u05EB-\u05EF\u05F5-\u060B\u060D-\u061A\u061C-\u061E\u0620\u063B-\u0640\u0653-\u065F\u066D-\u066F\u06D6-\u06EF\u06FA-\u0900\u0904\u093A-\u093B\u094E-\u094F\u0955-\u0957\u0971-\u0980\u0984\u098D-\u098E\u0991-\u0992\u09A9\u09B1\u09B3-\u09B5\u09BA-\u09BB\u09BD\u09C5-\u09C6\u09C9-\u09CA\u09CE-\u09D6\u09D8-\u09DB\u09DE\u09E4-\u09E5\u09FB-\u0A01\u0A03-\u0A04\u0A0B-\u0A0E\u0A11-\u0A12\u0A29\u0A31\u0A34\u0A37\u0A3A-\u0A3B\u0A43-\u0A46\u0A49-\u0A4A\u0A4D-\u0A58\u0A5D\u0A5F-\u0A65\u0A75-\u0A80\u0A84\u0A8C-\u0A8E\u0A91-\u0A92\u0AA9\u0AB1\u0AB4\u0ABA-\u0ABB\u0AC6\u0AC9-\u0ACA\u0ACE-\u0ACF\u0AD1-\u0ADF\u0AE1-\u0AE5\u0AF0-\u0B00\u0B04\u0B0D-\u0B0E\u0B11-\u0B12\u0B29\u0B31\u0B34-\u0B35\u0B3A-\u0B3B\u0B44-\u0B46\u0B49-\u0B4A\u0B4E-\u0B56\u0B58-\u0B5B\u0B5E\u0B62-\u0B65\u0B71-\u0B81\u0B84\u0B8B-\u0B8D\u0B91\u0B96-\u0B98\u0B9B\u0B9D\u0BA0-\u0BA2\u0BA5-\u0BA7\u0BAB-\u0BAD\u0BB6\u0BBA-\u0BBD\u0BC3-\u0BC5\u0BC9\u0BCE-\u0BD6\u0BD8-\u0BE6\u0BF3-\u0C00\u0C04\u0C0D\u0C11\u0C29\u0C34\u0C3A-\u0C3D\u0C45\u0C49\u0C4E-\u0C54\u0C57-\u0C5F\u0C62-\u0C65\u0C70-\u0C81\u0C84\u0C8D\u0C91\u0CA9\u0CB4\u0CBA-\u0CBD\u0CC5\u0CC9\u0CCE-\u0CD4\u0CD7-\u0CDD\u0CDF\u0CE2-\u0CE5\u0CF0-\u0D01\u0D04\u0D0D\u0D11\u0D29\u0D3A-\u0D3D\u0D44-\u0D45\u0D49\u0D4E-\u0D56\u0D58-\u0D5F\u0D62-\u0D65\u0D70-\u0D81\u0D84\u0D8C-\u0D8D\u0D91\u0DA9\u0DB1\u0DB4\u0DBA-\u0DBD\u0DC5\u0DC9\u0DCE-\u0DD4\u0DD6\u0DD8-\u0DDD\u0DDF\u0DE1-\u0DE6\u0DF7-\u0E00\u0E3B-\u0E3E\u0E4C\u0E5C-\u0E6F\u0E75-\u0E80\u0E83\u0E85-\u0E86\u0E89\u0E8B-\u0E8C\u0E8E-\u0E93\u0E98\u0EA0\u0EA4\u0EA6\u0EA8-\u0EA9\u0EAC\u0EBA\u0EBE-\u0EBF\u0EC5\u0EC7\u0ECE-\u0ECF\u0EDA-\u0EDB\u0EDE-\u0EEF\u0EF5-\u0FFF\u1023-\u1025\u102D\u1032\u103F\u104D-\u109F\u10C6-\u10CF\u10F7-\u10FA\u10FC-\u10FF\u115A-\u115E\u11A3-\u11A7\u11FA-\u1DFF\u1E9B-\u1E9F\u1EFA-\u1FFF\u200D-\u200F\u202A-\u202F\u2047-\u206F\u2071-\u2073\u208F-\u209F\u20AD-\u20CF\u20E2-\u20FF\u2139-\u2152\u2183-\u218F\u21EB-\u21FF\u22F2-\u22FF\u237B-\u23FF\u2425-\u243F\u244B-\u245F\u24EB-\u24FF\u2596-\u259F\u25F0-\u25FF\u2614-\u2619\u2670-\u2700\u2705\u270A-\u270B\u2728\u274C\u274E\u2753-\u2755\u2757\u275F-\u2760\u2768-\u2775\u2795-\u2797\u27B0\u27BF-\u2FFF\u3007\u3033-\u3035\u3037-\u303E\u3040\u3095-\u3098\u309F-\u30A0\u30FF-\u3104\u312D-\u3130\u318F-\u3191\u31A0-\u31FF\u321D-\u321F\u3244-\u325F\u327C-\u327E\u32B1-\u32CF\u32FF\u3358-\u337A\u33DE-\u4DFF\u9FA6-\uABFF\uD7A4-\uD7FF\uFA2E-\uFAFF\uFB07-\uFB1D\uFB1F-\uFE2F\uFE45-\uFE48\uFE53\uFE67\uFE6C-\uFE6F\uFE73\uFE75\uFEF5-\uFF00\uFF5F-\uFF60\uFFBF-\uFFC1\uFFC8-\uFFC9\uFFD0-\uFFD1\uFFD8-\uFFD9\uFFDD-\uFFDF\uFFE7\uFFEF-\U0010FFFF]', '', 'g'), NFD));
-- One '~' per non-ignorable NFKD code point before each special, then the special's rank character.
CREATE FUNCTION people.legacy_word_special(value text) RETURNS text
  LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
  AS $$
DECLARE
  ignorable CONSTANT text := '[\u01F6-\u01F9\u0218-\u024F\u02A9-\u02AF\u02DF\u02EA-\u02FF\u0349-\u036F\u0373\u0376-\u0379\u037B-\u037D\u037F-\u0383\u0387\u038B\u038D\u03A2\u03CF\u03D7-\u03D9\u03F3-\u0400\u040D\u0450\u045D\u0487-\u048F\u04CD-\u0530\u0557-\u0558\u0560\u0587-\u0588\u058A-\u0590\u05C4-\u05CF\u05EB-\u05EF\u05F5-\u060B\u060D-\u061A\u061C-\u061E\u0620\u063B-\u0640\u0653-\u065F\u066D-\u066F\u06D6-\u06EF\u06FA-\u0900\u0904\u093A-\u093B\u094E-\u094F\u0955-\u0957\u0971-\u0980\u0984\u098D-\u098E\u0991-\u0992\u09A9\u09B1\u09B3-\u09B5\u09BA-\u09BB\u09BD\u09C5-\u09C6\u09C9-\u09CA\u09CE-\u09D6\u09D8-\u09DB\u09DE\u09E4-\u09E5\u09FB-\u0A01\u0A03-\u0A04\u0A0B-\u0A0E\u0A11-\u0A12\u0A29\u0A31\u0A34\u0A37\u0A3A-\u0A3B\u0A43-\u0A46\u0A49-\u0A4A\u0A4D-\u0A58\u0A5D\u0A5F-\u0A65\u0A75-\u0A80\u0A84\u0A8C-\u0A8E\u0A91-\u0A92\u0AA9\u0AB1\u0AB4\u0ABA-\u0ABB\u0AC6\u0AC9-\u0ACA\u0ACE-\u0ACF\u0AD1-\u0ADF\u0AE1-\u0AE5\u0AF0-\u0B00\u0B04\u0B0D-\u0B0E\u0B11-\u0B12\u0B29\u0B31\u0B34-\u0B35\u0B3A-\u0B3B\u0B44-\u0B46\u0B49-\u0B4A\u0B4E-\u0B56\u0B58-\u0B5B\u0B5E\u0B62-\u0B65\u0B71-\u0B81\u0B84\u0B8B-\u0B8D\u0B91\u0B96-\u0B98\u0B9B\u0B9D\u0BA0-\u0BA2\u0BA5-\u0BA7\u0BAB-\u0BAD\u0BB6\u0BBA-\u0BBD\u0BC3-\u0BC5\u0BC9\u0BCE-\u0BD6\u0BD8-\u0BE6\u0BF3-\u0C00\u0C04\u0C0D\u0C11\u0C29\u0C34\u0C3A-\u0C3D\u0C45\u0C49\u0C4E-\u0C54\u0C57-\u0C5F\u0C62-\u0C65\u0C70-\u0C81\u0C84\u0C8D\u0C91\u0CA9\u0CB4\u0CBA-\u0CBD\u0CC5\u0CC9\u0CCE-\u0CD4\u0CD7-\u0CDD\u0CDF\u0CE2-\u0CE5\u0CF0-\u0D01\u0D04\u0D0D\u0D11\u0D29\u0D3A-\u0D3D\u0D44-\u0D45\u0D49\u0D4E-\u0D56\u0D58-\u0D5F\u0D62-\u0D65\u0D70-\u0D81\u0D84\u0D8C-\u0D8D\u0D91\u0DA9\u0DB1\u0DB4\u0DBA-\u0DBD\u0DC5\u0DC9\u0DCE-\u0DD4\u0DD6\u0DD8-\u0DDD\u0DDF\u0DE1-\u0DE6\u0DF7-\u0E00\u0E3B-\u0E3E\u0E4C\u0E5C-\u0E6F\u0E75-\u0E80\u0E83\u0E85-\u0E86\u0E89\u0E8B-\u0E8C\u0E8E-\u0E93\u0E98\u0EA0\u0EA4\u0EA6\u0EA8-\u0EA9\u0EAC\u0EBA\u0EBE-\u0EBF\u0EC5\u0EC7\u0ECE-\u0ECF\u0EDA-\u0EDB\u0EDE-\u0EEF\u0EF5-\u0FFF\u1023-\u1025\u102D\u1032\u103F\u104D-\u109F\u10C6-\u10CF\u10F7-\u10FA\u10FC-\u10FF\u115A-\u115E\u11A3-\u11A7\u11FA-\u1DFF\u1E9B-\u1E9F\u1EFA-\u1FFF\u200D-\u200F\u202A-\u202F\u2047-\u206F\u2071-\u2073\u208F-\u209F\u20AD-\u20CF\u20E2-\u20FF\u2139-\u2152\u2183-\u218F\u21EB-\u21FF\u22F2-\u22FF\u237B-\u23FF\u2425-\u243F\u244B-\u245F\u24EB-\u24FF\u2596-\u259F\u25F0-\u25FF\u2614-\u2619\u2670-\u2700\u2705\u270A-\u270B\u2728\u274C\u274E\u2753-\u2755\u2757\u275F-\u2760\u2768-\u2775\u2795-\u2797\u27B0\u27BF-\u2FFF\u3007\u3033-\u3035\u3037-\u303E\u3040\u3095-\u3098\u309F-\u30A0\u30FF-\u3104\u312D-\u3130\u318F-\u3191\u31A0-\u31FF\u321D-\u321F\u3244-\u325F\u327C-\u327E\u32B1-\u32CF\u32FF\u3358-\u337A\u33DE-\u4DFF\u9FA6-\uABFF\uD7A4-\uD7FF\uFA2E-\uFAFF\uFB07-\uFB1D\uFB1F-\uFE2F\uFE45-\uFE48\uFE53\uFE67\uFE6C-\uFE6F\uFE73\uFE75\uFEF5-\uFF00\uFF5F-\uFF60\uFFBF-\uFFC1\uFFC8-\uFFC9\uFFD0-\uFFD1\uFFD8-\uFFD9\uFFDD-\uFFDF\uFFE7\uFFEF-\U0010FFFF]';
BEGIN
  IF value !~ '[\u0001\u0002\u0003\u0004\u0005\u0006\u0007\u0008\u000E\u000F\u0010\u0011\u0012\u0013\u0014\u0015\u0016\u0017\u0018\u0019\u001A\u001B\u001C\u001D\u001E\u001F\u007F\u0080\u0081\u0082\u0083\u0084\u0085\u0086\u0087\u0088\u0089\u008A\u008B\u008C\u008D\u008E\u008F\u0090\u0091\u0092\u0093\u0094\u0095\u0096\u0097\u0098\u0099\u009A\u009B\u009C\u009D\u009E\u009F\u0027\uFF07\uFE63\u002D\uFF0D\u208B\u207B\u00AD\u2010\u2011\u2027\u2043\u2012\u2013\uFE58\u2014\u2015\u301C\u3030\uFE31\uFE32\u064B\uFE70\uFE71\u064C\uFE72\u064D\uFE74\u064E\uFE76\uFE77\u064F\uFE78\uFE79\u0650\uFE7A\uFE7B\u0652\uFE7E\uFE7F]' THEN
    RETURN '';
  END IF;
  RETURN (
    SELECT string_agg(repeat('~', length(regexp_replace(normalize(m[1], NFKD), ignorable, '', 'g'))) || translate(m[2], U&'\0001\0002\0003\0004\0005\0006\0007\0008\000E\000F\0010\0011\0012\0013\0014\0015\0016\0017\0018\0019\001A\001B\001C\001D\001E\001F\007F\0080\0081\0082\0083\0084\0085\0086\0087\0088\0089\008A\008B\008C\008D\008E\008F\0090\0091\0092\0093\0094\0095\0096\0097\0098\0099\009A\009B\009C\009D\009E\009F\0027\FF07\FE63\002D\FF0D\208B\207B\00AD\2010\2011\2027\2043\2012\2013\FE58\2014\2015\301C\3030\FE31\FE32\064B\FE70\FE71\064C\FE72\064D\FE74\064E\FE76\FE77\064F\FE78\FE79\0650\FE7A\FE7B\0652\FE7E\FE7F', U&'\0021\0022\0023\0024\0025\0026\0027\0028\0029\002A\002B\002C\002D\002E\002F\0030\0031\0032\0033\0034\0035\0036\0037\0038\0039\003A\003B\003C\003D\003E\003F\0040\0041\0042\0043\0044\0045\0046\0047\0048\0049\004A\004B\004C\004D\004E\004F\0050\0051\0052\0053\0054\0055\0056\0057\0058\0059\005A\005B\005C\005C\005D\005E\005E\005F\0060\0061\0062\0063\0064\0065\0066\0067\0068\0069\006A\006B\006C\006D\006E\006F\006F\006F\0070\0070\0071\0071\0072\0072\0072\0073\0073\0073\0074\0074\0074\0075\0075\0075'), '' ORDER BY n)
    FROM regexp_matches(regexp_replace(value, ignorable, '', 'g'), '([^\u0001\u0002\u0003\u0004\u0005\u0006\u0007\u0008\u000E\u000F\u0010\u0011\u0012\u0013\u0014\u0015\u0016\u0017\u0018\u0019\u001A\u001B\u001C\u001D\u001E\u001F\u007F\u0080\u0081\u0082\u0083\u0084\u0085\u0086\u0087\u0088\u0089\u008A\u008B\u008C\u008D\u008E\u008F\u0090\u0091\u0092\u0093\u0094\u0095\u0096\u0097\u0098\u0099\u009A\u009B\u009C\u009D\u009E\u009F\u0027\uFF07\uFE63\u002D\uFF0D\u208B\u207B\u00AD\u2010\u2011\u2027\u2043\u2012\u2013\uFE58\u2014\u2015\u301C\u3030\uFE31\uFE32\u064B\uFE70\uFE71\u064C\uFE72\u064D\uFE74\u064E\uFE76\uFE77\u064F\uFE78\uFE79\u0650\uFE7A\uFE7B\u0652\uFE7E\uFE7F]*)([\u0001\u0002\u0003\u0004\u0005\u0006\u0007\u0008\u000E\u000F\u0010\u0011\u0012\u0013\u0014\u0015\u0016\u0017\u0018\u0019\u001A\u001B\u001C\u001D\u001E\u001F\u007F\u0080\u0081\u0082\u0083\u0084\u0085\u0086\u0087\u0088\u0089\u008A\u008B\u008C\u008D\u008E\u008F\u0090\u0091\u0092\u0093\u0094\u0095\u0096\u0097\u0098\u0099\u009A\u009B\u009C\u009D\u009E\u009F\u0027\uFF07\uFE63\u002D\uFF0D\u208B\u207B\u00AD\u2010\u2011\u2027\u2043\u2012\u2013\uFE58\u2014\u2015\u301C\u3030\uFE31\uFE32\u064B\uFE70\uFE71\u064C\uFE72\u064D\uFE74\u064E\uFE76\uFE77\u064F\uFE78\uFE79\u0650\uFE7A\uFE7B\u0652\uFE7E\uFE7F])', 'g') WITH ORDINALITY AS t(m, n)
  );
END
$$;
-- The person name order in the two keys: last then first name, NULLs first, then userid.
DROP INDEX people.person_tenant_text_name_order_idx;
CREATE INDEX person_tenant_word_name_order_idx ON people.person (
  tenant_id,
  people.legacy_word_text(lname) COLLATE people.legacy_text_order NULLS FIRST,
  people.legacy_word_special(lname) COLLATE "C" NULLS FIRST,
  people.legacy_word_text(fname) COLLATE people.legacy_text_order NULLS FIRST,
  people.legacy_word_special(fname) COLLATE "C" NULLS FIRST,
  people.legacy_word_text(userid) COLLATE people.legacy_text_order NULLS FIRST,
  people.legacy_word_special(userid) COLLATE "C" NULLS FIRST,
  userid
);
